var a=[{title:`Cos’è l’allenamento concorrente`,text:`L’allenamento di forza mette alla prova quanta forza producono i muscoli, e l’esercizio aerobico migliora per quanto tempo riesci a continuare. Per la salute in generale trai beneficio da entrambi. Il cosiddetto effetto di interferenza descrive i casi in cui combinare allenamenti duri di entrambi i tipi può ridurre alcuni miglioramenti rispetto al farne solo uno.`},{title:`Cosa mostrano le rassegne`,text:`Una revisione sistematica ha rilevato che combinare allenamento aerobico e di forza in media non ha ridotto in modo significativo la crescita del muscolo intero né la forza massima. I miglioramenti nella forza esplosiva sono stati un po’ più influenzati, in particolare quando i due tipi di allenamento venivano fatti nella stessa sessione. L’esito esatto dipende da volume, tipo di esercizio, tempistica e storia di allenamento.`},{title:`Pianifica attorno alla tua priorità`,text:`Se il sollevamento massimale è il tuo obiettivo principale, fai il tuo miglior lavoro di forza prima del cardio duro, oppure metti le sessioni impegnative in giorni separati quando puoi. Se il tuo obiettivo è la forma generale, puoi combinare cardio facile e forza senza programmazioni elaborate. Recupero e carico di lavoro totale contano di più, e nessuno dei due tipi di allenamento è nemico dell’altro.`},{title:`Esempio`,text:`Due sessioni di forza total body a settimana più ciclismo o camminata moderati negli altri giorni possono sviluppare più capacità insieme. Un atleta di potenza agonista può essere più attento a non fare intervalli duri subito prima di sollevamenti esplosivi.`},{title:`Usare TrainUp`,text:`Scegli il tuo obiettivo principale in Profilo: forma generale, forza o condizionamento. Non ti servono giorni separati per tutto, e nessuna singola sessione di cardio cancella i tuoi guadagni muscolari.`}];var o=[{label:`Revisione sistematica: combinare esercizio aerobico e di forza`,url:`https://pubmed.ncbi.nlm.nih.gov/34757594/`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};